S = "Hakeem Force Academy"
QS = [
(S, "Who is known as the Tiger of Mysore?", ["Nawab of Bengal Mir Jafar", "Tipu Sultan", "Siraj-ud-Daulah", "Bahadur Shah Zafar"], 1, "Tipu Sultan, ruler of Mysore, was called the Tiger of Mysore for his bravery against the British.", "He was killed defending Srirangapatna in 1799 in the Fourth Anglo-Mysore War.", [768]),
(S, "How many Prime Ministers did Pakistan have from 1947 until the martial law of October 1958?", ["5", "6", "7", "8"], 2, "They were Liaquat Ali Khan, Khawaja Nazimuddin, Muhammad Ali Bogra, Chaudhry Muhammad Ali, H. S. Suhrawardy, I. I. Chundrigar and Feroz Khan Noon, which makes 7.", "Feroz Khan Noon was the last Prime Minister before Ayub Khan's martial law in 1958.", [399, 1876, 3444]),
(S, "Who gave the first Azan inside the Kaaba after the conquest of Makkah?", ["Hazrat Bilal (RA)", "Hazrat Umar (RA)", "Hazrat Abu Bakr (RA)", "Hazrat Ali (RA)"], 0, "On the day Makkah was conquered, the Prophet (PBUH) asked Hazrat Bilal (RA) to call the Azan from the roof of the Kaaba.", "Hazrat Bilal (RA) was the first Muezzin of Islam.", [4382]),
(S, "Fill in the blank: He is too weak ___ walk.", ["of", "to", "on", "for"], 1, "The pattern is too + adjective + to + verb, so the correct word is to.", "The sentence means that he is so weak that he cannot walk.", [839]),
(S, "Which PSL team won the title in two consecutive seasons, 2022 and 2023?", ["Islamabad United", "Multan Sultans", "Lahore Qalandars", "Quetta Gladiators"], 2, "Lahore Qalandars won the PSL final in 2022 and again in 2023, the only back-to-back titles in PSL history.", "Peshawar Zalmi are the champions of the 2026 season; Lahore also won in 2025.", [4274, 4317]),
(S, "Where is the tomb of the Sufi poet Bulleh Shah located?", ["Kasur", "Multan", "Pakpattan", "Sialkot"], 0, "Bulleh Shah is buried in Kasur, the city where he lived and taught.", "Bulleh Shah wrote in the Punjabi language and died in 1757.", [1227]),
(S, "Who inaugurated the Mazar-e-Quaid (Quaid-e-Azam Mausoleum) in Karachi?", ["Ayub Khan", "Liaquat Ali Khan", "Yahya Khan", "Zulfikar Ali Bhutto"], 2, "The mausoleum was opened to the public by President Yahya Khan in January 1971.", "Its construction was completed in 1970 and the architect was Yahya Merchant.", [4449]),
(S, "The Khilafat Movement in the subcontinent started after which war?", ["World War I", "World War II", "War of Independence 1857", "Balkan War of 1912"], 0, "After World War I the Ottoman Empire was defeated and its Caliphate was threatened, which led Indian Muslims to start the Khilafat Movement.", "The movement was led by Maulana Muhammad Ali Jauhar and Maulana Shaukat Ali.", [2639]),
(S, "How many oceans are there in the world?", ["3", "4", "5", "6"], 2, "The five oceans are the Pacific, Atlantic, Indian, Southern and Arctic Oceans.", "The Pacific Ocean is the largest and deepest ocean.", [1859]),
(S, "In which year of prophethood did the Muslims first migrate to Habsha (Abyssinia)?", ["1st year", "3rd year", "5th year", "10th year"], 2, "The first migration to Abyssinia took place in the 5th year of prophethood, around 615 CE.", "The Muslims were given shelter by the just king Najashi.", [3579]),
(S, "What is the height of the Eiffel Tower in Paris, including antennas, in metres?", ["About 230 m", "About 330 m", "About 430 m", "About 530 m"], 1, "The Eiffel Tower is about 330 metres tall including its antenna, which is about 1,083 feet.", "Sources differ slightly: the older figure of 324 m was used before antenna changes.", [445]),
(S, "What is Pakistan's top export product group?", ["Textiles", "Rice", "Cement", "Leather only"], 0, "Textiles and clothing make up more than half of Pakistan's total exports.", "Rice is Pakistan's biggest food export.", [624]),
(S, "A train covers 20 km in 1 hour 40 minutes. How far will it travel in 5 minutes?", ["1 km", "2 km", "0.5 km", "4 km"], 0, "1 hour 40 minutes is 100 minutes, so the train covers 20 / 100 = 0.2 km each minute. In 5 minutes it covers 5 x 0.2 = 1 km.", "The speed of this train is 12 km per hour.", [1964]),
(S, "The speed of a car is 60 km/h and a train goes at double that speed. How far does the train travel in 100 minutes?", ["100 km", "150 km", "200 km", "120 km"], 2, "Train speed is 2 x 60 = 120 km/h. In 100 minutes (5/3 hour) it covers 120 x 5/3 = 200 km.", "Distance equals speed multiplied by time.", [2591]),
(S, "A car goes at 60 km/h and a train goes twice as fast. How far does the train travel in 12 minutes?", ["12 km", "24 km", "20 km", "30 km"], 1, "Train speed is 120 km/h, which is 2 km per minute. In 12 minutes it covers 12 x 2 = 24 km.", "120 km/h is the same as 2 km per minute.", [1442]),
(S, "A car goes at 60 km/h and a train goes twice as fast. How far does the train travel in 30 minutes?", ["30 km", "45 km", "90 km", "60 km"], 3, "Train speed is 120 km/h. In 30 minutes (half an hour) it covers 120 x 1/2 = 60 km.", "The car would cover 30 km in the same time.", [1494]),
(S, "Who is called the Traveller of Islam?", ["Ibn Battuta", "Tariq bin Ziyad", "Ibn Khaldun", "Al-Biruni"], 0, "Ibn Battuta, the Moroccan explorer, travelled about 120,000 km across Africa, Asia and Europe in nearly 30 years.", "He wrote the famous travel book called the Rihla.", [373, 4469, 4470, 4529]),
(S, "In a bus 30 passengers are travelling and 2/3 of them are male. What percentage of the passengers are female?", ["25%", "30%", "33.33%", "66.67%"], 2, "Males are 2/3 x 30 = 20, so females are 30 - 20 = 10. Percentage of females = 10/30 x 100 = 33.33%.", "Females are exactly 1/3 of the passengers.", [2050]),
(S, "A man travels 90 km in 1 hour 40 minutes. In how many minutes will he cover 1 km?", ["0.9 minute", "1.11 minutes", "1.5 minutes", "2 minutes"], 1, "Total time is 100 minutes for 90 km, so time for 1 km = 100/90 = 1.11 minutes.", "His speed is 54 km per hour.", [1460]),
(S, "A person is travelling towards the north. After some time he turns left and then turns right. In which direction is he now going?", ["North", "South", "East", "West"], 0, "Turning left from north makes him face west. Turning right from west makes him face north again.", "Left and right turns in turn cancel each other.", [1466]),
(S, "A person is going towards the north. He turns left and then turns left again. In which direction is he now going?", ["East", "West", "North", "South"], 3, "Left from north is west. Left from west is south.", "Two left turns in a row reverse the direction.", [2038]),
(S, "Ali moves towards the north and then turns to his left. What is his direction now?", ["West", "East", "South", "North"], 0, "When facing north, the left side is west.", "When facing north, the right side is east.", [816]),
(S, "Which tribe of Pashtuns did Sher Shah Suri belong to?", ["Yusufzai", "Afridi", "Sur", "Khattak"], 2, "Sher Shah Suri belonged to the Sur tribe of the Pashtuns, which is why he is called Suri.", "His birth name was Farid Khan.", [1003]),
(S, "Sher Shah Suri belonged to which ethnic group?", ["Turk", "Pashtun", "Uzbek", "Persian"], 1, "Sher Shah Suri was a Pashtun (Afghan) from the Sur tribe.", "He defeated the Mughal emperor Humayun and ruled India from 1540 to 1545.", [2583, 2584]),
(S, "Who led the Quraysh army in the Battle of Badr?", ["Abu Sufyan", "Abu Jahl", "Khalid bin Waleed", "Ikrimah"], 1, "Abu Jahl commanded the Makkan army at Badr and was killed there.", "Badr was fought in 2 AH on 17 Ramadan.", [4591]),
(S, "What type of number is 0?", ["Natural number", "Whole number", "Negative number", "Prime number"], 1, "Whole numbers are 0, 1, 2, 3 and so on, so 0 is a whole number but not a natural number.", "Natural numbers start from 1.", [4335]),
(S, "After rearranging the letters of the word UEABYIFT, what is the last letter of the new word?", ["T", "F", "Y", "E"], 2, "The letters make the word BEAUTIFY, which ends with Y.", "BEAUTIFY means to make something beautiful.", [1521]),
(S, "Who was the leader of the hypocrites (Munafiqeen) in the Battle of Uhud?", ["Abu Amir", "Abdullah bin Ubayy", "Ikrimah", "Abu Lahab"], 1, "Abdullah bin Ubayy bin Salul withdrew with about 300 men before the battle began.", "This left the Muslims with about 700 men.", [4713, 4727]),
(S, "Who was the Man of the Tournament in the 1999 Cricket World Cup?", ["Shane Warne", "Lance Klusener", "Saeed Anwar", "Rahul Dravid"], 1, "South African all-rounder Lance Klusener was named Man of the Tournament in 1999.", "Australia won that World Cup, beating Pakistan in the final.", [4733]),
]
